import {TeggMarkdownEditor} from '../../dist/editor.js';
import {attachEditingUI} from '../../dist/ui.js';
import {katexEngine} from '../../dist/katex.js';
import {mermaidEngine} from '../../dist/mermaid.js';
import {graphvizEngine} from '../../dist/graphvizEngine.js';
import '../../dist/editor.css';
import '../../dist/ui.css';
import 'katex/dist/katex.min.css';

const native=window.__perfNative;
const frame=()=>new Promise(resolve=>native.raf(resolve));
const delay=ms=>new Promise(resolve=>native.timeout(resolve,ms));
const counts={change:0,state:0,outline:0,hostPending:0,enginePending:0,math:0,mermaid:0,graphviz:0};
const engines={math:(...args)=>{counts.math++;return katexEngine(...args);},mermaid:async(...args)=>{counts.mermaid++;counts.enginePending++;try{return await mermaidEngine(...args);}finally{counts.enginePending--;}},graphviz:async(...args)=>{counts.graphviz++;counts.enginePending++;try{return await graphvizEngine(...args);}finally{counts.enginePending--;}}};
const owned=new Set();let current;
function assert(condition,message){if(!condition)throw new Error(message);}
const button=(root,label)=>[...root.querySelectorAll('button')].find(node=>node.dataset.label===label||node.dataset.teggUiText===label||node.textContent===label);
const prefixes={table:'| Name | Value | Other |\n| --- | --- | --- |\n| target | old | third |\n'+Array.from({length:12},(_,i)=>`| row-${i} | value-${i} | third-${i} |\n`).join('')+'\n',math:'$$\nx^2+y\n$$\n\n',mermaid:'```mermaid\nflowchart TD\nA --> B\n```\n\n',graphviz:'```graphviz\ndigraph { a -> b }\n```\n\n'};
function fixture(kind,size){let seed=0x54454747;const random=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return seed>>>0;};let source=prefixes[kind];while(source.length<size)source+=`## Section ${random()%10000}\n\nReadable **mixed** text and [link](https://example.com) with value ${random()%10000}.\n\n`;const tail='\n\nInput sentence. ';return source.slice(0,size-tail.length)+tail;}
function mount(source,id='instance'){
  const root=document.createElement('section');root.className='instance';const surface=document.createElement('div'),tools=document.createElement('div');surface.className='surface';tools.className='tools';root.append(surface,tools);document.querySelector('main').append(root);
  const editor=new TeggMarkdownEditor(surface,{documentId:id,revision:'r1',profile:'tegg',source},{engines,onChange:()=>counts.change++,onStateChange:()=>counts.state++,onOutlineChange:()=>counts.outline++},'live');
  editor.view.dispatch({selection:{anchor:editor.view.state.doc.length}});editor.view.focus();
  const ui=attachEditingUI(editor.editing,tools,{chooseResource:({signal})=>new Promise(resolve=>{counts.hostPending++;const done=()=>{signal.removeEventListener('abort',done);counts.hostPending--;resolve(null);};if(signal.aborted)done();else signal.addEventListener('abort',done,{once:true});})});
  const instance={editor,ui,root,surface,tools};owned.add(instance);return instance;
}
function destroy(instance){instance.ui.destroy();instance.editor.destroy();instance.root.remove();owned.delete(instance);if(current===instance)current=undefined;}
async function settle(ms=350){await delay(ms);await frame();await frame();}
async function previewReady(instance,kind){const selector=kind==='math'?'.katex':'svg';const deadline=performance.now()+10000;while(!instance.tools.querySelector('.tegg-object-preview '+selector)){if(performance.now()>deadline)throw new Error('Optional '+kind+' preview did not render: '+instance.tools.textContent);await delay(20);}await frame();}
function openObject(instance,kind){instance.editor.view.focus();instance.ui.openObject(kind,{from:0,to:prefixes[kind].trimEnd().length});return instance.tools.querySelector('textarea');}
async function sample(run){const started=performance.now();run();const dispatch=performance.now()-started;await Promise.resolve();const notified=performance.now()-started;await frame();return {dispatch,notified,nextFrame:performance.now()-started};}
async function setup(kind,size){if(current)destroy(current);const source=fixture(kind,size);current=mount(source);await settle();const bytes=new TextEncoder().encode(source);return {kind,bytes:bytes.length,seed:'0x54454747',sha256:[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('')};}
async function tableSample(index,rectangle){const {root,editor}=current;const cell=[...root.querySelectorAll('.cm-live-table button')].find(node=>node.getAttribute('aria-label')?.startsWith('Edit table cell: ')&&node.textContent=== (index===0?'target':`target-${index-1}`));assert(cell,'Real table cell button missing for sample '+index);const result=await sample(()=>{cell.click();const input=root.querySelector('.cm-live-table-cell input:not([hidden])');assert(input,'Table input did not open');if(rectangle){const data=new DataTransfer();data.setData('text/plain',`target-${index}\tvalue-${index}`);const event=new ClipboardEvent('paste',{bubbles:true,cancelable:true});Object.defineProperty(event,'clipboardData',{value:data});input.dispatchEvent(event);assert(event.defaultPrevented,'Rectangle paste was not handled');}else{input.value=`target-${index}`;input.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:String(index)}));input.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));}});assert(editor.source.includes(`| target-${index} |`),'Table operation did not commit the intended cell');return result;}
async function prepareObject(kind,size){const meta=await setup(kind,size);openObject(current,kind);await previewReady(current,kind);current.original=current.editor.source;return meta;}
async function objectSample(kind,index){const raw=current.tools.querySelector('textarea');const draft=kind==='math'?`$$\nx^{${index}}+y\n$$`:kind==='mermaid'?`\`\`\`mermaid\nflowchart TD\nA --> B${index}\n\`\`\``:`\`\`\`graphviz\ndigraph { a -> b${index} }\n\`\`\``;const result=await sample(()=>{raw.value=draft;raw.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:String(index)}));});assert(current.editor.source===current.original,'Object preparation changed the source without Apply');return result;}
async function pauseObject(kind){await previewReadyAfterDelay(current,kind);}
async function previewReadyAfterDelay(instance,kind){await delay(280);await previewReady(instance,kind);}
function complexDraft(kind){return kind==='mermaid'?'```mermaid\nflowchart TD\n'+Array.from({length:200},(_,i)=>`N${i} --> N${i+1}`).join('\n')+'\n```':'```graphviz\ndigraph {\n'+Array.from({length:200},(_,i)=>`n${i} -> n${i+1};`).join('\n')+'\n}\n```';}
async function cancelSample(kind,index){const instance=current;openObject(instance,kind);const raw=instance.tools.querySelector('textarea'),draft=complexDraft(kind);const prior=counts[kind];raw.value=draft;raw.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:String(index)}));await delay(280);assert(instance.tools.querySelector('.tegg-object-preview')?.textContent.includes('too large'),'Complex draft did not enter explicit budget fallback');assert(counts[kind]===prior,'Over-budget draft invoked the synchronous/worker engine');const before=instance.editor.source;const result=await sample(()=>{const cancel=button(instance.tools,'Cancel');assert(cancel&&!cancel.disabled,'Cancel unavailable after degradation');cancel.click();assert(instance.tools.querySelector('.tegg-editing-panel').hidden,'Cancel failed to close panel');assert(instance.editor.view.hasFocus,'Cancel did not return focus to document');const end=instance.editor.view.state.doc.length;instance.editor.view.dispatch({changes:{from:end,insert:'.'},selection:{anchor:end+1}});});assert(instance.editor.source===before+'.','Document input was blocked after Cancel');return {...result,degraded:true,engineInvocations:counts[kind]-prior,draftBytes:new TextEncoder().encode(draft).length};}
async function cycle(id,render=false){const instance=mount(fixture('graphviz',2048),'cycle-'+id);instance.editor.view.dispatch({changes:{from:instance.editor.view.state.doc.length,insert:' edit'}});const session=instance.editor.editing.begin('selection',{from:instance.editor.view.state.doc.length,to:instance.editor.view.state.doc.length});instance.editor.editing.updateDraft(session.token,'not committed');instance.editor.editing.cancel(session.token);openObject(instance,'graphviz');if(render)await previewReady(instance,'graphviz');const raw=instance.tools.querySelector('textarea');raw.value=complexDraft('graphviz');raw.dispatchEvent(new Event('input'));instance.ui.close();instance.editor.view.dispatch({selection:{anchor:instance.editor.view.state.doc.length}});const task=instance.ui.chooseResource();await Promise.resolve();destroy(instance);await task;await Promise.resolve();}
async function eight(){const instances=Array.from({length:8},(_,i)=>mount(fixture('table',2048),'parallel-'+i));await settle();for(let i=0;i<instances.length;i++){const instance=instances[i];instance.editor.view.dispatch({changes:{from:instance.editor.view.state.doc.length,insert:` instance-${i}`}});instance.ui.openObject('link',{from:instance.editor.view.state.doc.length,to:instance.editor.view.state.doc.length});const raw=instance.tools.querySelector('textarea');raw.value=`[draft-${i}](next.md)`;raw.dispatchEvent(new Event('input'));assert(instance.editor.editing.session?.draft===raw.value,'Parallel instance draft unavailable');}const during={mounted:owned.size,editors:document.querySelectorAll('.cm-editor').length,uis:document.querySelectorAll('.tegg-editing-ui').length,resources:await window.__resourceSnapshot(),documents:instances.map(i=>i.editor.source.slice(-11))};assert(during.mounted===8&&during.editors===8&&during.uis===8,'Eight editors were not independently mounted');for(const instance of instances)destroy(instance);await settle();return during;}
window.interactionPerf={setup,tableSample,prepareObject,objectSample,pauseObject,cancelSample,cycle,eight,settle,finish:()=>{for(const instance of [...owned])destroy(instance);},snapshot:()=>({ownedInstances:owned.size,editorDOM:document.querySelectorAll('.cm-editor').length,uiDOM:document.querySelectorAll('.tegg-editing-ui').length,counts:{...counts}})};
